import java.util.*;

class Solution {
    public int minLength(String s) {
        char[] stack = new char[s.length()];
        int size = 0;
        for (char c : s.toCharArray()) {
            if (size > 0 && ((stack[size - 1] == 'A' && c == 'B') || (stack[size - 1] == 'C' && c == 'D'))) {
                size--;                 // snip the pair
            } else {
                stack[size++] = c;      // keep it
            }
        }
        return size;
    }
}

